 void start(){removeCallbacks(reconnect);if(engine!=null)engine.release();int buffer=client.prefs.getInt("buffer",1);int[][] values={{5000,15000,500,1500},{15000,50000,1500,3000},{30000,60000,3000,5000}};int[] v=values[buffer];DefaultLoadControl load=new DefaultLoadControl.Builder().setBufferDurationsMs(v[0],v[1],v[2],v[3]).build();
  DefaultHttpDataSource.Factory http=new DefaultHttpDataSource.Factory().setUserAgent("Blades360/1.0").setConnectTimeoutMs(12000).setReadTimeoutMs(20000).setAllowCrossProtocolRedirects(false).setDefaultRequestProperties(channel.headers);
  engine=new ExoPlayer.Builder(a).setMediaSourceFactory(new DefaultMediaSourceFactory(new DefaultDataSource.Factory(a,http))).setLoadControl(load).build();engine.setAudioAttributes(new AudioAttributes.Builder().setUsage(C.USAGE_MEDIA).setContentType(C.AUDIO_CONTENT_TYPE_MOVIE).build(),true);engine.setHandleAudioBecomingNoisy(true);video.setPlayer(engine);retries=0;status="Connecting…";
  engine.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(closed)return;if(state==Player.STATE_BUFFERING)status="Buffering…";else if(state==Player.STATE_READY){status="Playing";}else if(state==Player.STATE_ENDED)status="Stream ended";overlay.invalidate();}@Override public void onPlayerError(PlaybackException e){if(closed)return;int max=client.prefs.getInt("retries",3);if(retries<max){retries++;status="Stream interrupted · retry "+retries+" / "+max;postDelayed(reconnect,Math.min(10000,retries*2000));}else status="Stream unavailable · X Options to retry";overlay.invalidate();}@Override public void onTracksChanged(Tracks t){if(menu&&(page==1||page==2))buildOptions();}});
  MediaItem.Builder item=new MediaItem.Builder().setUri(override==null?channel.url:override).setMediaMetadata(new MediaMetadata.Builder().setTitle(channel.name).build());int format=client.prefs.getInt("format_"+channel.id,0);if(format==1)item.setMimeType(MimeTypes.APPLICATION_M3U8);else if(format==2)item.setMimeType(MimeTypes.VIDEO_MP2T);engine.setMediaItem(item.build());applyQuality(client.prefs.getInt("quality",0));engine.prepare();engine.play();client.recent(channel);}
