 void applyQuality(int choice){int[] bitrates={Integer.MAX_VALUE,8000000,4000000,1500000};int[] heights={Integer.MAX_VALUE,1080,720,480};engine.setTrackSelectionParameters(engine.getTrackSelectionParameters().buildUpon().setMaxVideoBitrate(bitrates[choice]).setMaxVideoSize(choice==0?Integer.MAX_VALUE:heights[choice]*16/9,heights[choice]).build());}
